item.stdout:
{"connection_id": "BC-583ddfba6d4b3d9b6f70", "ref": "1 Clement 46:5", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "division tears the community as Christ's body", "note": "Clement condemns strife as tearing apart members of one body; this makes communal loss the consequence of the division the commentary seeks to overcome."}
{"connection_id": "BC-92c9aace865a5184884f", "ref": "1 Clement 46:5", "target": "sec9", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "strife among one body", "note": "The commentary traces damage from disputes among believers; Clement asks why strife, anger, divisions and war appear among the community, confronting its internal fracture."}
{"connection_id": "BC-e533998b3850b937f8fa", "ref": "1 Clement 49:4", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "love acts in harmony and creates no schism", "note": "Clement describes love as refusing division and doing everything in harmony; this is a Christian interpretive expansion of the bond that the commentary sees replacing estrangement."}
{"connection_id": "BC-777e09861607bf25d3b0", "ref": "1 Clement 54:1", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "one person gives way so the community may live in peace", "note": "Clement asks anyone causing strife to leave voluntarily if needed so the flock can live peacefully; this gives the commentary's peace a costly communal practice."}
{"connection_id": "BC-cb594ab91539158626e0", "ref": "Didache 14:1", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "reconcile with an opponent before the communal meal", "note": "The Didache bars someone at odds with a fellow from joining the Eucharist until reconciliation; this gives the commentary's peace a concrete liturgical consequence."}
{"connection_id": "BC-dab0ef6f73200010d8d5", "ref": "Didache 14:2", "target": "sec9", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "reconcile before communal worship", "note": "The commentary repairs ties among believers; the Didache bars a person with a dispute from joining the assembly until reconciled, making peace a condition of its common offering."}
{"connection_id": "BC-3128dcd7bff6a3657a8d", "ref": "Didache 15:3", "target": "sec9", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "reprove one another in peace", "note": "The commentary turns adversarial truth claims into mutual counsel; the Didache directs communal reproof without anger and in peace, joining correction to a nonhostile manner."}
{"connection_id": "BC-f09f215374d33d60bd39", "ref": "Didache 2:7", "target": "sec9", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "correct rather than hate a person", "note": "The commentary's counsel must be joined to affection; the Didache forbids hatred and distinguishes those one should correct, pray for, or love beyond oneself."}
{"connection_id": "BC-08e28d20f938ad0b5608", "ref": "Didache 4:3", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "reconcile disputants, judge rightly, reprove without partiality", "note": "The teaching rejects division, orders reconciliation and fair judgment, then forbids partiality in reproof; it closely joins the commentary's peace, haqq, and mutual counsel."}
{"connection_id": "BC-3a65c884b9433514dd70", "ref": "Didache 4:3", "target": "sec9", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "make peace between those who quarrel", "note": "The commentary moves from arguing parties to active reconciliation; the Didache forbids causing division and directs its reader to make peace among people in dispute."}
{"connection_id": "BC-49802c3f2b557f238448", "ref": "Didache 4:8", "target": "sec9", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "share with a brother in need", "note": "The commentary's fellowship reaches the needy rather than merely speaking to them; the Didache tells its reader to share possessions with a brother and not claim them as exclusively one's own."}
{"connection_id": "BC-acf76758669f61d7c7fc", "ref": "Gospel of Thomas 25", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "love and guard the brother as one's own soul", "note": "The saying treats the brother's life as one's own to protect; it gives the commentary's close-friend image an unusually intimate ethical measure."}
{"connection_id": "BC-14b0b864d69c96838cb3", "ref": "SBLGNT:1Cor.1.10", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "one mind instead of divisions", "note": "The commentary turns reciprocal contention into joined counsel; Paul urges the community to agree in speech and be restored to one mind without divisions."}
{"connection_id": "BC-8c739fae978e92021917", "ref": "SBLGNT:1Cor.1.11", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "quarrels among brothers", "note": "The commentary begins with a community at odds; Paul reports quarrels among the Corinthian brothers, the precise communal fracture addressed by his appeal to unity."}
{"connection_id": "BC-25a6d0cc1be7024f45b0", "ref": "SBLGNT:1Cor.11.21", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "one hungry while another is full", "note": "The commentary cites failure to urge food for the needy; in the Corinthians' common meal, one goes hungry while another becomes drunk, exposing a failed shared table."}
{"connection_id": "BC-c5e4628fcb9d03e8b712", "ref": "SBLGNT:1Cor.11.22", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "humiliation of those with nothing", "note": "The commentary's failed urging to feed the poor has communal consequences; Paul rebukes the Corinthians for shaming members who have nothing at their shared meal."}
{"connection_id": "BC-dd891d95dab06453d1ce", "ref": "SBLGNT:1Cor.11.33", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "wait for one another at the meal", "note": "The commentary's reciprocity must include material care; Paul tells the gathered Corinthians to wait for one another when they eat, answering the hungry member's exclusion in the same scene."}
{"connection_id": "BC-b1200ce0596bb8d4cd9d", "ref": "SBLGNT:1Cor.12.25", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "members care equally, without division", "note": "Paul's body image rejects division and makes members care for one another; it pictures mutual attachment as protection against isolation."}
{"connection_id": "BC-47fac4d7c18713d8f43c", "ref": "SBLGNT:1Cor.12.25", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "members care for each other without division", "note": "The commentary's reciprocal ethic overcomes separated parties; Paul's body image says members should have the same care for one another so the body has no division."}
{"connection_id": "BC-09c652f8935d98c02998", "ref": "SBLGNT:1Cor.12.26", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "one member's suffering is shared by all", "note": "The body's members suffer and rejoice together; this turns the commentary's human-in-loss image into shared rather than solitary experience."}
{"connection_id": "BC-99eb10efb78d43ecf9a8", "ref": "SBLGNT:1Cor.12.26", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "members suffer and rejoice together", "note": "The commentary's one-sided isolation becomes shared life; Paul's members suffer or rejoice together as each member is affected."}
{"connection_id": "BC-d552f08ebe90ea8611d9", "ref": "SBLGNT:1Cor.13.4", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "love is patient and kind", "note": "Paul makes patience and kindness qualities of love between people; this gives the commentary's ṣabr a relational rather than solitary form."}
{"connection_id": "BC-906275fc977ce844f84e", "ref": "SBLGNT:1Cor.13.4", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "love is patient", "note": "The commentary's affectionate bond is maintained by sabr; Paul's description of love begins with patience and kindness, placing endurance inside interpersonal love."}
{"connection_id": "BC-bc0ba84323cea138afef", "ref": "SBLGNT:1Cor.13.6", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "love rejoices with the truth", "note": "Paul joins truth with love's response; this directly meets the commentary's shift from haqq as a contested claim to a shared good."}
{"connection_id": "BC-15bf9191c0c5530bd127", "ref": "SBLGNT:1Cor.13.6", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "love rejoices with truth", "note": "The commentary binds love to mutual transmission of haqq; Paul says love does not rejoice in wrongdoing but rejoices with truth."}
{"connection_id": "BC-813af020f4046d8fe573", "ref": "SBLGNT:1Cor.13.7", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "love bears and endures", "note": "The commentary's companion stays with the community in patience; Paul's love bears and endures all things, giving that steadfastness a relational subject."}
{"connection_id": "BC-0c7a1c5566912190cf99", "ref": "SBLGNT:1Cor.3.3", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "jealousy and strife among believers", "note": "The commentary starts with rival claims inside a group; Paul points to jealousy and strife among the Corinthians as evidence of immature, merely human behavior."}
{"connection_id": "BC-6b07eaea29df4bf451ec", "ref": "SBLGNT:1Cor.6.5", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "judge disputes between brothers", "note": "The commentary's rival claims need someone to reconcile or judge them; Paul asks whether no wise person in the community can decide a matter between brothers."}
{"connection_id": "BC-97754a8915aac537c567", "ref": "SBLGNT:1Cor.6.6", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "brother sues brother", "note": "The commentary's first scene is two sides disputing right despite their possible bond; Paul names the scandal of a brother bringing a brother to court before unbelievers."}
{"connection_id": "BC-4f0a3197b3a18937d076", "ref": "SBLGNT:1Cor.6.7", "target": "sec9", "tradition": "incil", "kind": "karsi_anlati", "basis": "accepting wrong instead of litigating with a brother", "note": "The commentary turns haqq into truth passed mutually, while Paul says that lawsuits among believers are already defeat and asks why they do not accept being wronged; the differing remedy is the point."}
{"connection_id": "BC-694c8528c714c0749a13", "ref": "SBLGNT:1Cor.6.7", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "lawsuits already a defeat", "note": "The commentary's human being is in loss until a shared ethic replaces contention; Paul calls lawsuits among believers already a defeat and asks why they do not bear wrong."}
{"connection_id": "BC-4f2c75b356ddd0ee4973", "ref": "SBLGNT:1Cor.6.8", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "wrong and defraud brothers", "note": "The commentary's claimed right can become injury to the other side; Paul says the litigating Corinthians themselves wrong and defraud their own brothers, reversing the ethic of mutual benefit."}
{"connection_id": "BC-4bbe946307f9402a5ecd", "ref": "SBLGNT:1John.1.7", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "walking in light yields fellowship with one another", "note": "The letter joins shared truthfulness before God to fellowship among believers; this connects the commentary's haqq with its movement toward closeness."}
{"connection_id": "BC-f200070e18e1fac67d60", "ref": "SBLGNT:1John.3.14", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "love of brothers and escape from death", "note": "The commentary contrasts the human in loss with believers joined by affection; John says love for brothers marks a passage from death to life."}
{"connection_id": "BC-9f5765ded3cbfbab29cb", "ref": "SBLGNT:1John.3.16", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "give life for brothers", "note": "The commentary's close friendship issues in righteous action; John says Christ's laying down his life teaches believers to lay down their lives for brothers."}
{"connection_id": "BC-767ceba15bf8aaaf5243", "ref": "SBLGNT:1John.3.17", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "material care for needy brother", "note": "The commentary invokes the failure to encourage food for the poor; John asks how God's love can remain in one who sees a needy brother and shuts up compassion."}
{"connection_id": "BC-5b9e658c7876bebde582", "ref": "SBLGNT:1John.3.18", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "love in deed and truth", "note": "The commentary's joined good deeds and shared haqq require action; John tells the community to love in deed and truth, not merely in speech."}
{"connection_id": "BC-e7f66832c51ba70d5d59", "ref": "SBLGNT:1John.4.20", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "claiming love for God while hating a brother is false", "note": "The letter tests religious claim against treatment of the visible brother; this challenges any haqq claim detached from mutual care."}
{"connection_id": "BC-d36c56e832239092e8f7", "ref": "SBLGNT:1John.4.20", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "God-love tested by brother-love", "note": "The commentary insists on concrete closeness between believers; John calls one who claims to love God while hating a visible brother a liar."}
{"connection_id": "BC-a9cba03144a4586c8fdf", "ref": "SBLGNT:1John.4.21", "target": "sec9", "tradition": "incil", "kind": "motif", "basis": "love of God entails love of brother", "note": "The commentary binds faith to affection among companions; John says the command received from God is that the one loving God must also love his brother."}

