+{"connection_id":"BC-583ddfba6d4b3d9b6f70","ref":"1 Clement 46:5","status":"unavailable","reason":"1 Clement is absent from the frozen local snapshot; the body-division wording cannot be checked here.","paragraphs":[26],"evidence":[],"annotations":[]}
+{"connection_id":"BC-92c9aace865a5184884f","ref":"1 Clement 46:5","status":"unavailable","reason":"The Clement text has no local locator, so the proposed interpretation of communal strife remains unverified.","paragraphs":[26],"evidence":[],"annotations":[]}
+{"connection_id":"BC-e533998b3850b937f8fa","ref":"1 Clement 49:4","status":"unavailable","reason":"The proposed Clement love and harmony wording is absent from available local witnesses.","paragraphs":[26],"evidence":[],"annotations":[]}
