+{"connection_id":"BC-dab0ef6f73200010d8d5","ref":"Didache 14:2","status":"unavailable","reason":"No local Didache locator verifies the assembly and offering claim.","paragraphs":[28],"evidence":[],"annotations":[]}
+{"connection_id":"BC-3128dcd7bff6a3657a8d","ref":"Didache 15:3","status":"unavailable","reason":"The proposed peaceful reproof wording cannot be checked without a local Didache text.","paragraphs":[27],"evidence":[],"annotations":[]}
