+{"connection_id":"BC-3a65c884b9433514dd70","ref":"Didache 4:3","status":"unavailable","reason":"The alleged peacemaking instruction is in an absent secondary witness and cannot be quoted.","paragraphs":[28],"evidence":[],"annotations":[]}
+{"connection_id":"BC-49802c3f2b557f238448","ref":"Didache 4:8","status":"unavailable","reason":"The sharing instruction is not verifiable from the frozen local sources.","paragraphs":[27],"evidence":[],"annotations":[]}
