+{"connection_id":"BC-e985abd0b74b673a1eb6","ref":"SBLGNT:Jas.3.17","status":"accepted","reason":"The verse describes heavenly wisdom as peaceable, gentle and merciful, supplying the manner of counsel behind 3:18's peace-making result.","paragraphs":[28],"evidence":["SBLGNT:Jas.3.17","SBLGNT:Jas.3.18"],"annotations":["S103-INC-MTF-007"]}
+{"connection_id":"BC-1678b89bd0bc50187eee","ref":"SBLGNT:Jas.3.18","status":"accepted","reason":"The Greek directly combines righteousness, peaceful sowing and peacemakers, a tight ethical triad for paragraph 28.","paragraphs":[28],"evidence":["SBLGNT:Jas.3.17","SBLGNT:Jas.3.18"],"annotations":["S103-INC-MTF-007"]}
