+{"connection_id":"BC-2dad83057f2fd8984660","ref":"WLC:Prov.18.17","status":"accepted","reason":"The Hebrew says the first litigant seems right until the other examines him, a precise check on the two initial claims.","paragraphs":[26],"evidence":["WLC:Prov.18.17","WLC:Prov.12.15"],"annotations":["S103-TEV-MTF-001"]}
