+{"connection_id":null,"origin":"research","ref":"WLC:Ps.39.7","status":"rejected","reason":"Hebrew צבר depicts accumulating possessions without knowing who will gather them, not communal endurance or patient companionship.","paragraphs":[26],"evidence":["WLC:Ps.39.7"],"annotations":[]}
